  let response:Response;
  if(platform){const request=new Request(service.origin+path,init);if(platform.trusted)Object.defineProperty(request,'cf',{value:{colo:'LOCAL-TEST'},configurable:true});if(platform.address)request.headers.set('cf-connecting-ip',platform.address);response=await worker.fetch(request,{...service.env,AUTH_SECRET:secret,APP_ORIGIN:service.origin,APP_ENV:'production',RESEND_API_KEY:undefined,MAIL_FROM:undefined});}
