  const mailRows=Array.from({length:2700},(_,i)=>service.env.DB.prepare('INSERT INTO mail_reservation(id,day,month) VALUES(?,?,?)').bind('synthetic-historical-month-'+i,'2000-01-'+String(Math.floor(i/90)+1).padStart(2,'0'),'2000-01'));for(let i=0;i<mailRows.length;i+=50)await service.env.DB.batch(mailRows.slice(i,i+50));await assert.rejects(()=>service.env.DB.prepare("INSERT INTO mail_reservation(id,day,month) VALUES('synthetic-month-over','2000-01-31','2000-01')").run(),/mail_budget_exhausted/);observations.push({surface:'controlled-historical-month-sql',monthlyReservations:2700,nextDay31Denied:true});
