async function focusedModerationFixture(label:string,privateRelease?:string){
 await mkdir('server/.local',{recursive:true});const directory=await mkdtemp(resolve('server/.local/moderation-'+label+'-'));await chmod(directory,0o700);const sourceBefore=await sourceIdentity(),service=await localService(directory,crypto.randomUUID()+crypto.randomUUID(),true,{port:8799,privateRelease});const actors:Record<string,Actor>={},requests:Array<{path:string;method:string;actor:string;status:number;error?:string}>=[];
 async function call(path:string,status:number,method='GET',role='guest',body?:unknown,headers:Record<string,string>={}){const response=await fetch(service.origin+path,{method,redirect:'manual',headers:{origin:service.origin,'content-type':'application/json',cookie:actors[role]?.cookie??'',...headers},body:body===undefined?undefined:body instanceof Uint8Array?Uint8Array.from(body):JSON.stringify(body)});let error:string|undefined;if(response.status>=400)try{error=(await response.clone().json() as {error:string}).error;}catch{}requests.push({path,method,actor:role,status:response.status,...error?{error}:{}});assert.equal(response.status,status,method+' '+path+' '+role+' '+error);return response;}
 async function login(role:string){const email='independent-'+label+'-'+role+'@polyspoon.invalid';await call('/api/auth/sign-in/magic-link',200,'POST','guest',{email,callbackURL:'/catalog'});const mail=await service.env.DB.prepare('SELECT url FROM local_mail_outbox WHERE recipient=? ORDER BY created_at DESC').bind(email).first<{url:string}>();assert.ok(mail);const response=await fetch(mail.url,{redirect:'manual'}),cookie=response.headers.getSetCookie().map(value=>value.split(';')[0]).join('; ');const me=await fetch(service.origin+'/api/me',{headers:{cookie}});assert.equal(me.status,200);actors[role]={id:(await me.json() as {id:string}).id,cookie};return actors[role]!;}
 async function seedUser(name:string){const id='independent-'+label+'-'+name+'-'+crypto.randomUUID();await service.env.DB.prepare('INSERT INTO user(id,name,email,emailVerified,createdAt,updatedAt) VALUES(?,?,?,1,?,?)').bind(id,'Synthetic '+name,id+'@polyspoon.invalid',Date.now(),Date.now()).run();await service.env.DB.prepare("INSERT INTO member(user_id,status,created_at) VALUES(?,'active',?)").bind(id,Date.now()).run();return id;}
 async function stop(passed:boolean,observations:unknown[]){await service.stop();await mkdir('server/test-evidence/moderation-independent',{recursive:true});await writeFile('server/test-evidence/moderation-independent/'+label+'-observations.json',JSON.stringify({status:passed?'passed':'failed',syntheticFixture:true,port:8799,sourceBefore,sourceAfter:await sourceIdentity(),requests,observations,serviceStopped:true,limits:['Fresh independent HTTP fixture only; no live8797mutation or model/artistic acceptance.']},null,2)+'\n');}
 return {service,actors,call,login,seedUser,stop};
}

